statements:
-- Delve data model
-- Run this in the Supabase SQL editor (Project > SQL Editor > New query).
-- Every screen in the app reads and writes these tables directly.

create extension if not exists "pgcrypto";

-- One row per signed-in user. Supabase creates auth.users automatically on
-- sign-in; this table holds the display info the app actually shows.
create table profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null,
  created_at timestamptz not null default now()
);

-- A campaign is one ongoing game (e.g. "The sunken keep"). map_url/map_cols/
-- map_rows describe the uploaded map image and the grid overlaid on it;
-- party_row/party_col track where the party marker sits on that grid.
create table campaigns (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  system text not null default 'Shadowdark',
  gm_type text not null check (gm_type in ('human', 'ai')),
  gm_user_id uuid references profiles(id),
  join_code text not null unique,
  session_number int not null default 1,
  status text not null default 'active' check (status in ('active', 'paused', 'ended')),
  map_url text,
  map_cols int not null default 10,
  map_rows int not null default 6,
  party_row int,
  party_col int,
  created_at timestamptz not null default now()
);

-- Who belongs to a campaign, and whether they're the GM or a player.
-- A GM campaign has one member with role='gm'; an AI-GM campaign has none.
create table campaign_members (
  campaign_id uuid references campaigns(id) on delete cascade,
  user_id uuid references profiles(id) on delete cascade,
  role text not null check (role in ('gm', 'player')),
  joined_at timestamptz not null default now(),
  primary key (campaign_id, user_id)
);

-- Characters belong to a user but are scoped to one campaign, so the same
-- player can have a different character per campaign (matches the character
-- picker screen showing characters "from this campaign or a past one").
create table characters (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  owner_user_id uuid references profiles(id) on delete cascade,
  name text not null,
  ancestry text not null,
  class text not null,
  level int not null default 1,
  stats jsonb not null, -- {"str":10,"dex":10,"con":10,"int":10,"wis":10,"cha":10}
  hp int not null,
  max_hp int not null,
  ac int not null default 10,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

-- Monsters in the current fight. hidden=true means the GM sees it but
-- players don't yet -- RLS below enforces that.
create table encounter_monsters (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  name text not null,
  ac int not null,
  hp int not null,
  max_hp int not null,
  hidden boolean not null default false,
  created_at timestamptz not null default now()
);

-- GM-only notes until explicitly revealed to the party.
create table gm_notes (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  text text not null,
  revealed boolean not null default false,
  created_at timestamptz not null default now()
);

-- One row per grid cell overlaid on the campaign's uploaded map image.
-- state starts 'fog' (an opaque tile hiding the map underneath) and flips
-- to 'explored' (transparent, map shows through) permanently -- per the
-- honor-system fog-of-war design -- unless the GM uses the "re-fog" control
-- to clear cells for a story reason like amnesia. Cells are created lazily:
-- a missing row for (campaign, row, col) just means 'fog'. Only the GM can
-- write to this table -- players can read it (RLS below) so fog clears
-- live for everyone, but revealing/re-fogging is a GM-only action.
create table map_cells (
  campaign_id uuid references campaigns(id) on delete cascade,
  row int not null,
  col int not null,
  state text not null default 'fog' check (state in ('fog', 'explored')),
  updated_at timestamptz not null default now(),
  primary key (campaign_id, row, col)
);

-- The shared scene log: narration, chat, GM lines, and dice rolls (both
-- app-rolled and self-reported), all in one ordered feed.
create table scene_log (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  type text not null check (type in ('narration', 'chat', 'gm', 'roll')),
  sender_user_id uuid references profiles(id),
  sender_name text not null,
  text text not null,
  roll_source text check (roll_source in ('app', 'self')),
  created_at timestamptz not null default now()
);

-- Current initiative order for a campaign. Kept as one jsonb row per
-- campaign rather than one row per combatant since it's small, changes as
-- a unit each round, and just needs to broadcast over realtime.
create table turn_order (
  campaign_id uuid primary key references campaigns(id) on delete cascade,
  order_list jsonb not null default '[]',
  updated_at timestamptz not null default now()
);

-- Lightweight group polls, e.g. the "where to next?" vote on the map tab.
-- unique(campaign_id, poll_key, voter_user_id) means re-voting changes your
-- vote instead of adding a second one -- and scopes that uniqueness to a
-- single campaign, so the same poll_key in two different campaigns doesn't
-- collide for the same player.
create table votes (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  poll_key text not null,
  option_key text not null,
  option_label text not null,
  voter_user_id uuid references profiles(id),
  created_at timestamptz not null default now(),
  unique (campaign_id, poll_key, voter_user_id)
);

-- ---------------------------------------------------------------------
-- Auto-create a profile row whenever someone signs up for the first time,
-- so profiles.display_name always has something sensible without the app
-- needing a separate "finish your profile" step.
-- ---------------------------------------------------------------------

create or replace function handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data->>'display_name', split_part(new.email, '@', 1)));
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_user();

-- Auto-add the creator as a campaign_members row the instant a campaign is
-- inserted. Without this, "create campaign" fails RLS: the client's
-- .insert().select() needs the SELECT policy below (is_campaign_member) to
-- pass for the row it just inserted, but that's only true once a membership
-- row exists -- and this trigger makes sure one does before the INSERT's
-- RETURNING is evaluated.
create or replace function handle_new_campaign()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.campaign_members (campaign_id, user_id, role)
  values (new.id, auth.uid(), case when new.gm_type = 'human' then 'gm' else 'player' end)
  on conflict (campaign_id, user_id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_campaign_created on campaigns;
create trigger on_campaign_created
  after insert on campaigns
  for each row execute function handle_new_campaign();

-- ---------------------------------------------------------------------
-- Row level security: every table is scoped to campaigns a user belongs
-- to. gm_notes additionally hides unrevealed notes from non-GM members,
-- and encounter_monsters hides hidden monsters the same way.
-- ---------------------------------------------------------------------

alter table profiles enable row level security;
alter table campaigns enable row level security;
alter table campaign_members enable row level security;
alter table characters enable row level security;
alter table encounter_monsters enable row level security;
alter table gm_notes enable row level security;
alter table map_cells enable row level security;
alter table scene_log enable row level security;
alter table turn_order enable row level security;
alter table votes enable row level security;

create or replace function is_campaign_member(target_campaign_id uuid)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from campaign_members
    where campaign_id = target_campaign_id and user_id = auth.uid()
  );
$$;

create or replace function is_campaign_gm(target_campaign_id uuid)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from campaign_members
    where campaign_id = target_campaign_id and user_id = auth.uid() and role = 'gm'
  );
$$;

create policy "profiles are self-readable" on profiles
  for select using (true); -- display names are fine to be publicly readable

create policy "users can update their own profile" on profiles
  for update using (id = auth.uid());

create policy "members can read their campaigns" on campaigns
  for select using (is_campaign_member(id));

create policy "authenticated users can create campaigns" on campaigns
  for insert with check (auth.uid() is not null);

create policy "gm can update their campaign" on campaigns
  for update using (is_campaign_gm(id));

create policy "members can read the member list" on campaign_members
  for select using (is_campaign_member(campaign_id));

create policy "users can add themselves as a member" on campaign_members
  for insert with check (user_id = auth.uid());

create policy "users can leave a campaign" on campaign_members
  for delete using (user_id = auth.uid());

create policy "members can read campaign characters" on characters
  for select using (is_campaign_member(campaign_id));

create policy "owners can write their own characters" on characters
  for insert with check (owner_user_id = auth.uid() and is_campaign_member(campaign_id));

create policy "owners and gm can update characters" on characters
  for update using (owner_user_id = auth.uid() or is_campaign_gm(campaign_id));

create policy "gm sees all monsters, players see non-hidden" on encounter_monsters
  for select using (
    is_campaign_gm(campaign_id) or (is_campaign_member(campaign_id) and hidden = false)
  );

create policy "only gm writes monsters" on encounter_monsters
  for all using (is_campaign_gm(campaign_id));

create policy "gm sees all notes, players see revealed only" on gm_notes
  for select using (
    is_campaign_gm(campaign_id) or (is_campaign_member(campaign_id) and revealed = true)
  );

create policy "only gm writes notes" on gm_notes
  for all using (is_campaign_gm(campaign_id));

create policy "members can read map cells" on map_cells
  for select using (is_campaign_member(campaign_id));

create policy "gm can reveal map cells" on map_cells
  for insert with check (is_campaign_gm(campaign_id));

create policy "gm can update map cells" on map_cells
  for update using (is_campaign_gm(campaign_id));

create policy "gm can delete map cells" on map_cells
  for delete using (is_campaign_gm(campaign_id));

create policy "members can read the scene log" on scene_log
  for select using (is_campaign_member(campaign_id));

create policy "members can post to the scene log" on scene_log
  for insert with check (is_campaign_member(campaign_id));

create policy "members can read turn order" on turn_order
  for select using (is_campaign_member(campaign_id));

create policy "gm updates turn order" on turn_order
  for all using (is_campaign_gm(campaign_id));

create policy "members can read and cast votes" on votes
  for select using (is_campaign_member(campaign_id));

create policy "members can vote" on votes
  for insert with check (is_campaign_member(campaign_id) and voter_user_id = auth.uid());

create policy "members can change their own vote" on votes
  for update using (voter_user_id = auth.uid());

-- ---------------------------------------------------------------------
-- Storage: a public "maps" bucket holds uploaded map images. Public read
-- means anyone with the URL can view an image (fine -- URLs aren't
-- guessable and images aren't sensitive); only signed-in users can upload.
-- ---------------------------------------------------------------------

insert into storage.buckets (id, name, public)
values ('maps', 'maps', true)
on conflict (id) do nothing;

create policy "anyone can view map images" on storage.objects
  for select using (bucket_id = 'maps');

create policy "authenticated users can upload map images" on storage.objects
  for insert with check (bucket_id = 'maps' and auth.uid() is not null);

create policy "authenticated users can replace map images" on storage.objects
  for update using (bucket_id = 'maps' and auth.uid() is not null);

-- ---------------------------------------------------------------------
-- Realtime: these tables are enabled in the supabase_realtime publication
-- so every screen updates live for everyone connected, no refresh needed:
-- map_cells, campaigns, scene_log, encounter_monsters, gm_notes,
-- turn_order, votes, characters.
-- ---------------------------------------------------------------------

-- Delve — Dice engine (chunk 1 of the GM-brain integration)
create table dice_rolls (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  roller_user_id uuid references profiles(id),
  roller_name text not null,
  notation text not null,
  mode text not null check (mode in ('flat', 'advantage', 'disadvantage', 'self')),
  reason text,
  breakdown text not null,
  total int not null,
  raw_d20 int,
  is_crit boolean not null default false,
  is_fumble boolean not null default false,
  created_at timestamptz not null default now()
);

alter table scene_log add column dice_roll_id uuid references dice_rolls(id);

alter table dice_rolls enable row level security;

create policy "members can read a campaign's dice rolls" on dice_rolls
  for select using (is_campaign_member(campaign_id));

create policy "members can log dice rolls" on dice_rolls
  for insert with check (is_campaign_member(campaign_id));

alter publication supabase_realtime add table dice_rolls;

-- Delve — Character sheet (chunk 2 of the GM-brain integration)
alter table characters add column alignment text;
alter table characters add column background text;
alter table characters add column xp int not null default 0;
alter table characters add column coin numeric not null default 0;

create table character_gear (
  id uuid primary key default gen_random_uuid(),
  character_id uuid references characters(id) on delete cascade,
  name text not null,
  slots numeric not null default 1,
  equipped boolean not null default false,
  quantity int not null default 1,
  notes text,
  created_at timestamptz not null default now()
);

create table character_talents (
  id uuid primary key default gen_random_uuid(),
  character_id uuid references characters(id) on delete cascade,
  source text not null,
  description text not null,
  created_at timestamptz not null default now()
);

alter table character_gear enable row level security;
alter table character_talents enable row level security;

create policy "members can read a character's gear" on character_gear
  for select using (
    exists (
      select 1 from characters c
      where c.id = character_gear.character_id and is_campaign_member(c.campaign_id)
    )
  );

create policy "owner or gm can write a character's gear" on character_gear
  for all using (
    exists (
      select 1 from characters c
      where c.id = character_gear.character_id
        and (c.owner_user_id = auth.uid() or is_campaign_gm(c.campaign_id))
    )
  );

create policy "members can read a character's talents" on character_talents
  for select using (
    exists (
      select 1 from characters c
      where c.id = character_talents.character_id and is_campaign_member(c.campaign_id)
    )
  );

create policy "owner or gm can write a character's talents" on character_talents
  for all using (
    exists (
      select 1 from characters c
      where c.id = character_talents.character_id
        and (c.owner_user_id = auth.uid() or is_campaign_gm(c.campaign_id))
    )
  );

alter publication supabase_realtime add table character_gear;
alter publication supabase_realtime add table character_talents;

alter table characters add column avatar_url text;

insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', true)
on conflict (id) do nothing;

create policy "anyone can view character avatars" on storage.objects
  for select using (bucket_id = 'avatars');

create policy "character owner can upload their avatar" on storage.objects
  for insert with check (
    bucket_id = 'avatars'
    and exists (
      select 1 from characters c
      where c.id::text = (storage.foldername(name))[1]
        and c.owner_user_id = auth.uid()
    )
  );

create policy "character owner can replace their avatar" on storage.objects
  for update using (
    bucket_id = 'avatars'
    and exists (
      select 1 from characters c
      where c.id::text = (storage.foldername(name))[1]
        and c.owner_user_id = auth.uid()
    )
  );

create table campaign_threads (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  title text not null,
  description text,
  status text not null default 'open' check (status in ('open', 'resolved', 'abandoned')),
  created_at timestamptz not null default now()
);

create table campaign_clocks (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  name text not null,
  segments_filled int not null default 0,
  segments_total int not null default 4,
  created_at timestamptz not null default now()
);

create table campaign_timeline_entries (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  session_number int,
  entry text not null,
  created_at timestamptz not null default now()
);

alter table campaign_threads enable row level security;
alter table campaign_clocks enable row level security;
alter table campaign_timeline_entries enable row level security;

create policy "members can read campaign threads" on campaign_threads
  for select using (is_campaign_member(campaign_id));

create policy "gm writes campaign threads" on campaign_threads
  for all using (is_campaign_gm(campaign_id));

create policy "members can read campaign clocks" on campaign_clocks
  for select using (is_campaign_member(campaign_id));

create policy "gm writes campaign clocks" on campaign_clocks
  for all using (is_campaign_gm(campaign_id));

create policy "members can read the timeline" on campaign_timeline_entries
  for select using (is_campaign_member(campaign_id));

create policy "gm writes the timeline" on campaign_timeline_entries
  for all using (is_campaign_gm(campaign_id));

alter publication supabase_realtime add table campaign_threads;
alter publication supabase_realtime add table campaign_clocks;
alter publication supabase_realtime add table campaign_timeline_entries;

alter table campaigns add column session_active boolean not null default false;

create table campaign_light_sources (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  character_id uuid references characters(id) on delete set null,
  name text not null,
  total_minutes int not null,
  remaining_minutes numeric not null,
  lit boolean not null default false,
  lit_at timestamptz,
  created_at timestamptz not null default now()
);

alter table campaign_light_sources enable row level security;

create policy "members can read light sources" on campaign_light_sources
  for select using (is_campaign_member(campaign_id));

create policy "owner or gm can write light sources" on campaign_light_sources
  for all using (
    is_campaign_gm(campaign_id)
    or (
      character_id is not null and exists (
        select 1 from characters c
        where c.id = campaign_light_sources.character_id and c.owner_user_id = auth.uid()
      )
    )
  );

alter publication supabase_realtime add table campaign_light_sources;

alter table campaigns add column is_public boolean not null default true;
alter table campaigns add column join_password_hash text;

create policy "anyone can read public campaigns" on campaigns
  for select using (is_public = true);

drop policy if exists "users can add themselves as a member" on campaign_members;
create policy "users can add themselves to public campaigns" on campaign_members
  for insert with check (
    user_id = auth.uid()
    and exists (select 1 from campaigns c where c.id = campaign_members.campaign_id and c.is_public = true)
  );

create or replace function join_campaign_by_code(p_code text, p_password text default null)
returns table (id uuid, name text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_campaign campaigns%rowtype;
begin
  select * into v_campaign from campaigns where join_code = upper(trim(p_code));

  if not found then
    raise exception 'No campaign found with that code.';
  end if;

  if not v_campaign.is_public and v_campaign.join_password_hash is not null then
    if p_password is null or v_campaign.join_password_hash <> crypt(p_password, v_campaign.join_password_hash) then
      raise exception 'Incorrect password.';
    end if;
  end if;

  insert into campaign_members (campaign_id, user_id, role)
  values (v_campaign.id, auth.uid(), 'player')
  on conflict (campaign_id, user_id) do nothing;

  return query select v_campaign.id, v_campaign.name;
end;
$$;

revoke all on function join_campaign_by_code(text, text) from public;
grant execute on function join_campaign_by_code(text, text) to authenticated;

create or replace function set_campaign_privacy(p_campaign_id uuid, p_is_public boolean, p_password text default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not is_campaign_gm(p_campaign_id) then
    raise exception 'Only the GM can change campaign privacy.';
  end if;

  if p_is_public then
    update campaigns set is_public = true where id = p_campaign_id;
    return;
  end if;

  if p_password is not null and length(p_password) > 0 then
    update campaigns set is_public = false, join_password_hash = crypt(p_password, gen_salt('bf')) where id = p_campaign_id;
  else
    update campaigns set is_public = false where id = p_campaign_id and join_password_hash is not null;
    if not found then
      raise exception 'A password is required to make this campaign private.';
    end if;
  end if;
end;
$$;

revoke all on function set_campaign_privacy(uuid, boolean, text) from public;
grant execute on function set_campaign_privacy(uuid, boolean, text) to authenticated;

create table rules_documents (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null references profiles(id) on delete cascade,
  system text not null default 'Shadowdark',
  title text not null,
  description text,
  kind text not null check (kind in ('file', 'link')),
  file_path text,
  external_url text,
  created_at timestamptz not null default now(),
  constraint rules_documents_kind_payload check (
    (kind = 'file' and file_path is not null and external_url is null)
    or (kind = 'link' and external_url is not null and file_path is null)
  )
);

alter table rules_documents enable row level security;

create or replace function can_read_rules_documents(target_owner uuid, target_system text)
returns boolean
language sql
security definer
stable
as $$
  select target_owner = auth.uid() or exists (
    select 1 from campaign_members cm
    join campaigns c on c.id = cm.campaign_id
    where cm.user_id = auth.uid()
      and c.gm_user_id = target_owner
      and c.system = target_system
  );
$$;

create policy "gm and their players can read rules documents" on rules_documents
  for select using (can_read_rules_documents(owner_user_id, system));

create policy "owner manages their rules documents" on rules_documents
  for all using (owner_user_id = auth.uid()) with check (owner_user_id = auth.uid());

insert into storage.buckets (id, name, public)
values ('rules', 'rules', false)
on conflict (id) do nothing;

create policy "gm uploads their own rules files" on storage.objects
  for insert with check (
    bucket_id = 'rules' and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "gm deletes their own rules files" on storage.objects
  for delete using (
    bucket_id = 'rules' and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "members can read rules files they're entitled to" on storage.objects
  for select using (
    bucket_id = 'rules' and exists (
      select 1 from rules_documents rd
      where rd.file_path = storage.objects.name
        and can_read_rules_documents(rd.owner_user_id, rd.system)
    )
  );

create table campaign_npcs (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  name text not null,
  ancestry text,
  role text,
  location text,
  alignment text,
  attitude text,
  status text not null default 'Alive',
  notes text,
  created_at timestamptz not null default now()
);

create table campaign_factions (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  name text not null,
  type text,
  leader text,
  territory text,
  goal text,
  disposition text,
  status_clock text,
  notes text,
  created_at timestamptz not null default now()
);

create table campaign_treasure (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid references campaigns(id) on delete cascade,
  session_number int,
  item text not null,
  type text,
  qty_value text,
  found_at text,
  held_by text,
  identified boolean,
  notes text,
  created_at timestamptz not null default now()
);

alter table campaign_npcs enable row level security;
alter table campaign_factions enable row level security;
alter table campaign_treasure enable row level security;

create policy "members can read npcs" on campaign_npcs
  for select using (is_campaign_member(campaign_id));
create policy "gm writes npcs" on campaign_npcs
  for all using (is_campaign_gm(campaign_id));

create policy "members can read factions" on campaign_factions
  for select using (is_campaign_member(campaign_id));
create policy "gm writes factions" on campaign_factions
  for all using (is_campaign_gm(campaign_id));

create policy "members can read treasure" on campaign_treasure
  for select using (is_campaign_member(campaign_id));
create policy "gm writes treasure" on campaign_treasure
  for all using (is_campaign_gm(campaign_id));

alter publication supabase_realtime add table campaign_npcs;
alter publication supabase_realtime add table campaign_factions;
alter publication supabase_realtime add table campaign_treasure;

alter table scene_log drop constraint scene_log_type_check;
alter table scene_log add constraint scene_log_type_check
  check (type in ('narration', 'chat', 'gm', 'roll', 'ai_gm'));

create table character_spells (
  id uuid primary key default gen_random_uuid(),
  character_id uuid references characters(id) on delete cascade,
  name text not null,
  tier int not null default 1,
