-- A full rest is one atomic action: consume a ration, restore HP, reset
-- daily feature uses, and begin a fresh spell cycle.
create or replace function complete_character_rest(p_character_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_character characters%rowtype;
  v_ration character_gear%rowtype;
  v_rations_remaining int;
begin
  select *
  into v_character
  from characters
  where id = p_character_id
  for update;

  if not found or not (
    v_character.owner_user_id = auth.uid()
    or is_campaign_gm(v_character.campaign_id)
  ) then
    raise exception 'Character not found, or you cannot rest this character.';
  end if;

  select *
  into v_ration
  from character_gear
  where character_id = p_character_id
    and lower(name) in ('ration', 'rations')
    and quantity > 0
  order by created_at
  limit 1
  for update;

  if not found then
    raise exception 'A full rest requires one ration.';
  end if;

  if v_ration.quantity = 1 then
    delete from character_gear where id = v_ration.id;
    v_rations_remaining := 0;
  else
    update character_gear
    set quantity = quantity - 1
    where id = v_ration.id;
    v_rations_remaining := v_ration.quantity - 1;
  end if;

  update characters
  set hp = max_hp
  where id = p_character_id;

  update character_features
  set uses_current = uses_max
  where character_id = p_character_id
    and uses_max is not null;

  update character_spells
  set lost = false,
      succeeded_since_rest = false,
      last_check_natural = null,
      last_check_total = null,
      last_check_succeeded = null,
      last_check_at = null
  where character_id = p_character_id;

  return jsonb_build_object(
    'character_id', p_character_id,
    'hp', v_character.max_hp,
    'rations_remaining', v_rations_remaining
  );
end;
$$

create or replace function adjust_character_resource(
  p_character_id uuid,
  p_resource text,
  p_delta numeric,
  p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_character characters%rowtype;
  v_before numeric;
  v_after numeric;
begin
  if p_resource not in ('hp', 'xp', 'coin') then
    raise exception 'Unsupported character resource.';
  end if;

  if p_delta is null or p_delta = 0 then
    raise exception 'Resource adjustment must be non-zero.';
  end if;

  if p_resource in ('hp', 'xp') and trunc(p_delta) <> p_delta then
    raise exception 'HP and XP adjustments must be whole numbers.';
  end if;

  select *
  into v_character
  from characters
  where id = p_character_id
  for update;

  if not found or not (
    v_character.owner_user_id = auth.uid()
    or is_campaign_gm(v_character.campaign_id)
  ) then
    raise exception 'Character not found, or you cannot adjust this character.';
  end if;

  v_before := case p_resource
    when 'hp' then v_character.hp
    when 'xp' then v_character.xp
    when 'coin' then v_character.coin
  end;

  v_after := case p_resource
    when 'hp' then greatest(0, least(v_character.max_hp, v_before + p_delta))
    else greatest(0, v_before + p_delta)
  end;

  if p_resource = 'hp' then
    update characters set hp = v_after::int where id = p_character_id;
  elsif p_resource = 'xp' then
    update characters set xp = v_after::int where id = p_character_id;
  else
    update characters set coin = v_after where id = p_character_id;
  end if;

  insert into campaign_events (
    campaign_id, actor_user_id, event_type, entity_type, entity_id, payload
  ) values (
    v_character.campaign_id,
    auth.uid(),
    'character.resource_adjusted',
    'character',
    p_character_id,
    jsonb_build_object(
      'resource', p_resource,
      'before', v_before,
      'after', v_after,
      'requested_delta', p_delta,
      'applied_delta', v_after - v_before,
      'reason', nullif(btrim(p_reason), '')
    )
  );

  return jsonb_build_object(
    'character_id', p_character_id,
    'resource', p_resource,
    'before', v_before,
    'after', v_after,
    'applied_delta', v_after - v_before
  );
end;
$$

-- Extend the existing atomic rest command so rests are also part of the
-- campaign's durable history.
create or replace function complete_character_rest(p_character_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_character characters%rowtype;
  v_ration character_gear%rowtype;
  v_rations_remaining int;
begin
  select *
  into v_character
  from characters
  where id = p_character_id
  for update;

  if not found or not (
    v_character.owner_user_id = auth.uid()
    or is_campaign_gm(v_character.campaign_id)
  ) then
    raise exception 'Character not found, or you cannot rest this character.';
  end if;

  select *
  into v_ration
  from character_gear
  where character_id = p_character_id
    and lower(name) in ('ration', 'rations')
    and quantity > 0
  order by created_at
  limit 1
  for update;

  if not found then
    raise exception 'A full rest requires one ration.';
  end if;

  if v_ration.quantity = 1 then
    delete from character_gear where id = v_ration.id;
    v_rations_remaining := 0;
  else
    update character_gear
    set quantity = quantity - 1
    where id = v_ration.id;
    v_rations_remaining := v_ration.quantity - 1;
  end if;

  update characters set hp = max_hp where id = p_character_id;
  update character_features
    set uses_current = uses_max
    where character_id = p_character_id and uses_max is not null;
  update character_spells
    set lost = false,
        succeeded_since_rest = false,
        last_check_natural = null,
        last_check_total = null,
        last_check_succeeded = null,
        last_check_at = null
    where character_id = p_character_id;

  insert into campaign_events (
    campaign_id, actor_user_id, event_type, entity_type, entity_id, payload
  ) values (
    v_character.campaign_id,
    auth.uid(),
    'character.full_rest_completed',
    'character',
    p_character_id,
    jsonb_build_object(
      'hp_before', v_character.hp,
      'hp_after', v_character.max_hp,
      'ration_item_id', v_ration.id,
      'rations_remaining', v_rations_remaining
    )
  );

  return jsonb_build_object(
    'character_id', p_character_id,
    'hp', v_character.max_hp,
    'rations_remaining', v_rations_remaining
  );
end;
$$

create or replace function add_character_gear(
  p_character_id uuid,
  p_name text,
  p_slots numeric default 1,
  p_quantity int default 1,
  p_notes text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_character characters%rowtype;
  v_item character_gear%rowtype;
begin
  select * into v_character from characters where id = p_character_id;
  if not found or not (
    v_character.owner_user_id = auth.uid()
    or is_campaign_gm(v_character.campaign_id)
  ) then
    raise exception 'Character not found, or you cannot manage this character.';
  end if;
  if nullif(btrim(p_name), '') is null
    or p_slots is null or p_slots < 0
    or p_quantity is null or p_quantity < 1 then
    raise exception 'Gear requires a name, non-negative slots, and positive quantity.';
  end if;

  insert into character_gear (character_id, name, slots, quantity, notes, equipped)
  values (
    p_character_id, btrim(p_name), p_slots, p_quantity,
    nullif(btrim(p_notes), ''), false
  )
  returning * into v_item;

  insert into campaign_events (
    campaign_id, actor_user_id, event_type, entity_type, entity_id, payload
  ) values (
    v_character.campaign_id, auth.uid(), 'character.gear_added',
    'character_gear', v_item.id, jsonb_build_object('item', to_jsonb(v_item))
  );

  return to_jsonb(v_item);
end;
$$

create or replace function set_character_gear_equipped(
  p_gear_id uuid,
  p_equipped boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item character_gear%rowtype;
  v_character characters%rowtype;
  v_dex int;
  v_dex_mod int;
  v_armor character_gear%rowtype;
  v_has_shield boolean;
  v_ac int;
begin
  select g.* into v_item
  from character_gear g
  where g.id = p_gear_id
  for update;

  if not found then raise exception 'Gear not found.'; end if;
  select * into v_character
  from characters
  where id = v_item.character_id
  for update;
  if not (
    v_character.owner_user_id = auth.uid()
    or is_campaign_gm(v_character.campaign_id)
  ) then
    raise exception 'Gear not found, or you cannot manage it.';
  end if;

  update character_gear set equipped = p_equipped where id = p_gear_id
  returning * into v_item;

  v_dex := coalesce((v_character.stats->>'dex')::int, 10);
  v_dex_mod := case
    when v_dex >= 18 then 4 when v_dex >= 16 then 3
    when v_dex >= 14 then 2 when v_dex >= 12 then 1
    when v_dex >= 10 then 0 when v_dex >= 8 then -1
    when v_dex >= 6 then -2 when v_dex >= 4 then -3 else -4
  end;

  select * into v_armor
  from character_gear
  where character_id = v_character.id
    and equipped and base_ac is not null and not is_shield
  order by created_at
  limit 1;
  select exists (
    select 1 from character_gear
    where character_id = v_character.id and equipped and is_shield
  ) into v_has_shield;

  v_ac := case
    when v_armor.id is null then 10 + v_dex_mod
    else v_armor.base_ac + case when v_armor.dex_applies then v_dex_mod else 0 end
  end + case when v_has_shield then 2 else 0 end;
  update characters set ac = v_ac where id = v_character.id;

  insert into campaign_events (
    campaign_id, actor_user_id, event_type, entity_type, entity_id, payload
  ) values (
    v_character.campaign_id, auth.uid(), 'character.gear_equipped',
    'character_gear', v_item.id,
