create or replace function set_campaign_session_active(
  p_campaign_id uuid,
  p_active boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_campaign campaigns%rowtype;
  v_now timestamptz := clock_timestamp();
  v_affected int;
begin
  select * into v_campaign
  from campaigns where id = p_campaign_id
  for update;
  if not found or not (
    is_campaign_gm(p_campaign_id)
    or (
      v_campaign.gm_type = 'ai'
      and p_active
      and is_campaign_member(p_campaign_id)
    )
  ) then
    raise exception 'Campaign not found, or you are not its GM.';
  end if;

  if p_active then
    update campaign_light_sources
    set lit_at = v_now
    where campaign_id = p_campaign_id and lit and lit_at is null;
  else
    update campaign_light_sources
    set remaining_minutes = greatest(
          0, remaining_minutes - extract(epoch from (v_now - lit_at)) / 60
        ),
        lit_at = null
    where campaign_id = p_campaign_id and lit and lit_at is not null;
  end if;
  get diagnostics v_affected = row_count;

  update campaigns set session_active = p_active where id = p_campaign_id;
  insert into campaign_events (
    campaign_id, actor_user_id, event_type, entity_type, entity_id, payload
  ) values (
    p_campaign_id, auth.uid(), 'campaign.session_activity_changed',
    'campaign', p_campaign_id,
    jsonb_build_object(
      'before', v_campaign.session_active, 'after', p_active,
      'light_sources_updated', v_affected
    )
  );
  return jsonb_build_object(
    'campaign_id', p_campaign_id, 'session_active', p_active,
    'light_sources_updated', v_affected
  );
end;
$$

-- Generate app dice on the server and reserve direct inserts for clearly
-- labeled, self-reported physical rolls.

create or replace function roll_dice_expression(p_notation text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_clean text := lower(regexp_replace(coalesce(p_notation, ''), '\s+', '', 'g'));
  v_match text[];
  v_sign int;
  v_token text;
  v_count int;
  v_sides int;
  v_roll int;
  v_index int;
  v_subtotal int;
  v_total int := 0;
  v_parts text[] := '{}';
  v_rolls text[];
  v_dice_terms int := 0;
  v_raw_candidate int;
  v_single_positive_d20 boolean := false;
  v_total_dice int := 0;
begin
  if length(v_clean) > 100 or v_clean !~
    '^[+-]?([0-9]*d[0-9]+|[0-9]+)([+-]([0-9]*d[0-9]+|[0-9]+))*$' then
    raise exception 'Bad dice notation.';
  end if;

  for v_match in
    select regexp_matches(v_clean, '([+-]?)([0-9]*d[0-9]+|[0-9]+)', 'g')
  loop
    v_sign := case when v_match[1] = '-' then -1 else 1 end;
    v_token := v_match[2];

    if position('d' in v_token) > 0 then
      v_count := coalesce(nullif(split_part(v_token, 'd', 1), '')::int, 1);
      v_sides := split_part(v_token, 'd', 2)::int;
      if v_count < 1 or v_count > 100 or v_sides < 2 or v_sides > 1000 then
        raise exception 'Dice terms support 1-100 dice with 2-1000 sides.';
      end if;
      v_total_dice := v_total_dice + v_count;
      if v_total_dice > 100 then raise exception 'A roll may contain at most 100 dice.'; end if;

      v_dice_terms := v_dice_terms + 1;
      v_rolls := '{}';
      v_subtotal := 0;
      for v_index in 1..v_count loop
        v_roll := floor(random() * v_sides)::int + 1;
        v_rolls := array_append(v_rolls, v_roll::text);
        v_subtotal := v_subtotal + v_roll;
        if v_count = 1 and v_sides = 20 then
          v_raw_candidate := v_roll;
          v_single_positive_d20 := v_sign > 0;
        end if;
      end loop;
      v_total := v_total + v_sign * v_subtotal;
      v_parts := array_append(
        v_parts,
        (case when v_sign > 0 then '+' else '-' end)
          || v_count || 'd' || v_sides || '[' || array_to_string(v_rolls, ',') || ']'
      );
    else
      v_sides := v_token::int;
      v_total := v_total + v_sign * v_sides;
      v_parts := array_append(
        v_parts, (case when v_sign > 0 then '+' else '-' end) || v_sides
      );
    end if;
  end loop;

  return jsonb_build_object(
    'total', v_total,
    'breakdown', ltrim(array_to_string(v_parts, ' '), '+'),
    'raw_d20', case when v_dice_terms = 1 then v_raw_candidate else null end,
    'is_single_d20', v_dice_terms = 1 and v_single_positive_d20
  );
end;
$$

create or replace function roll_campaign_dice(
  p_campaign_id uuid,
  p_notation text,
  p_mode text default 'flat',
  p_reason text default null,
  p_roller_name text default null
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_first jsonb;
  v_second jsonb;
  v_kept jsonb;
  v_roll dice_rolls%rowtype;
  v_scene scene_log%rowtype;
  v_roller_user_id uuid;
  v_roller_name text;
  v_reason text := nullif(btrim(p_reason), '');
  v_mode_label text;
  v_flag text;
  v_text text;
begin
  if not is_campaign_member(p_campaign_id) then
    raise exception 'Campaign not found, or you are not a member.';
  end if;
  if p_mode is null or p_mode not in ('flat', 'advantage', 'disadvantage') then
    raise exception 'Unsupported dice mode.';
  end if;
  if length(coalesce(v_reason, '')) > 500 then
    raise exception 'Roll reason is too long.';
  end if;

  if nullif(btrim(p_roller_name), '') is not null then
    if not is_campaign_gm(p_campaign_id) then
      raise exception 'Only the GM can roll for an unowned subject.';
    end if;
    v_roller_user_id := null;
    v_roller_name := btrim(p_roller_name);
  else
    v_roller_user_id := auth.uid();
    select display_name into v_roller_name from profiles where id = auth.uid();
    if nullif(btrim(v_roller_name), '') is null then
      raise exception 'Your profile needs a display name before rolling.';
    end if;
  end if;

  v_first := roll_dice_expression(p_notation);
  if p_mode in ('advantage', 'disadvantage') then
    if not (v_first->>'is_single_d20')::boolean then
      raise exception 'Advantage/disadvantage require one positive d20 plus modifiers.';
    end if;
    v_second := roll_dice_expression(p_notation);
    v_kept := case
      when p_mode = 'advantage'
        and (v_first->>'total')::int >= (v_second->>'total')::int then v_first
      when p_mode = 'disadvantage'
        and (v_first->>'total')::int <= (v_second->>'total')::int then v_first
      else v_second
    end;
    v_kept := jsonb_set(
      v_kept, '{breakdown}',
      to_jsonb('[' || (v_first->>'breakdown') || '] vs ['
        || (v_second->>'breakdown') || ']')
    );
  else
    v_kept := v_first;
  end if;

  insert into dice_rolls (
    campaign_id, roller_user_id, roller_name, notation, mode, reason,
    breakdown, total, raw_d20, is_crit, is_fumble
  ) values (
    p_campaign_id, v_roller_user_id, v_roller_name,
    lower(regexp_replace(p_notation, '\s+', '', 'g')), p_mode, v_reason,
    v_kept->>'breakdown', (v_kept->>'total')::int,
    (v_kept->>'raw_d20')::int,
    coalesce((v_kept->>'raw_d20')::int = 20, false),
    coalesce((v_kept->>'raw_d20')::int = 1, false)
  )
  returning * into v_roll;

  v_mode_label := case
    when p_mode = 'advantage' then ' (advantage)'
    when p_mode = 'disadvantage' then ' (disadvantage)'
    else ''
  end;
  v_flag := case
    when v_roll.is_crit then ' — CRITICAL!'
    when v_roll.is_fumble then ' — fumble!'
    else ''
  end;
  v_text := 'rolled ' || v_roll.notation || v_mode_label || ': '
    || v_roll.total || v_flag
    || case when v_reason is not null then ' — ' || v_reason else '' end;

  insert into scene_log (
    campaign_id, type, sender_user_id, sender_name, text,
    roll_source, dice_roll_id
  ) values (
    p_campaign_id, 'roll', v_roller_user_id, v_roller_name, v_text,
    'app', v_roll.id
  )
  returning * into v_scene;

  return jsonb_build_object('roll', to_jsonb(v_roll), 'scene_entry', to_jsonb(v_scene));
end;
$$

-- Echo authoritative resource/rest changes into the scene log.
--
-- adjust_character_resource and complete_character_rest have recorded
-- every HP/XP/coin change and full rest in campaign_events since 025, but
-- nothing ever surfaced that in the UI -- players had no way to see it
-- without opening a character sheet. The scene log is the one feed
-- everyone at the table is already reading (same pattern roll_campaign_dice
-- already uses for dice), so both commands now also drop a short
-- 'narration' line there. Re-creating both functions in full since
-- CREATE OR REPLACE requires the complete body, not a diff.

create or replace function adjust_character_resource(
p_character_id uuid,
p_resource text,
p_delta numeric,
p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
v_character characters%rowtype;
v_before numeric;
v_after numeric;
v_delta_label text;
v_resource_label text;
v_reason text := nullif(btrim(p_reason), '');
begin
if p_resource not in ('hp', 'xp', 'coin') then
raise exception 'Unsupported character resource.';
end if;

if p_delta is null or p_delta = 0 then
raise exception 'Resource adjustment must be non-zero.';
end if;

if p_resource in ('hp', 'xp') and trunc(p_delta) <> p_delta then
raise exception 'HP and XP adjustments must be whole numbers.';
end if;

select *
into v_character
from characters
where id = p_character_id
for update;

if not found or not (
v_character.owner_user_id = auth.uid()
or is_campaign_gm(v_character.campaign_id)
) then
raise exception 'Character not found, or you cannot adjust this character.';
end if;

v_before := case p_resource
when 'hp' then v_character.hp
when 'xp' then v_character.xp
when 'coin' then v_character.coin
end;

v_after := case p_resource
when 'hp' then greatest(0, least(v_character.max_hp, v_before + p_delta))
else greatest(0, v_before + p_delta)
end;

if p_resource = 'hp' then
update characters set hp = v_after::int where id = p_character_id;
elsif p_resource = 'xp' then
update characters set xp = v_after::int where id = p_character_id;
else
update characters set coin = v_after where id = p_character_id;
end if;

insert into campaign_events (
campaign_id, actor_user_id, event_type, entity_type, entity_id, payload
) values (
v_character.campaign_id,
auth.uid(),
'character.resource_adjusted',
'character',
p_character_id,
jsonb_build_object(
'resource', p_resource,
'before', v_before,
'after', v_after,
'requested_delta', p_delta,
'applied_delta', v_after - v_before,
'reason', v_reason
)
);

v_resource_label := case p_resource when 'hp' then 'HP' when 'xp' then 'XP' else 'coin' end;
v_delta_label := (case when (v_after - v_before) > 0 then '+' else '' end) || (v_after - v_before)::text;

insert into scene_log (
campaign_id, type, sender_user_id, sender_name, text
) values (
v_character.campaign_id,
'narration',
auth.uid(),
v_character.name,
v_character.name || ': ' || v_delta_label || ' ' || v_resource_label
|| case when v_reason is not null then ' — ' || v_reason else '' end
);

return jsonb_build_object(
'character_id', p_character_id,
'resource', p_resource,
'before', v_before,
'after', v_after,
'applied_delta', v_after - v_before
);
end;
$$;

revoke all on function adjust_character_resource(uuid, text, numeric, text) from public;
grant execute on function adjust_character_resource(uuid, text, numeric, text) to authenticated;

create or replace function complete_character_rest(p_character_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
v_character characters%rowtype;
v_ration character_gear%rowtype;
v_rations_remaining int;
begin
select *
into v_character
from characters
where id = p_character_id
for update;

if not found or not (
v_character.owner_user_id = auth.uid()
or is_campaign_gm(v_character.campaign_id)
) then
raise exception 'Character not found, or you cannot rest this character.';
end if;

select *
into v_ration
from character_gear
where character_id = p_character_id
and lower(name) in ('ration', 'rations')
and quantity > 0
order by created_at
limit 1
for update;

if not found then
raise exception 'A full rest requires one ration.';
end if;

if v_ration.quantity = 1 then
delete from character_gear where id = v_ration.id;
v_rations_remaining := 0;
else
update character_gear
set quantity = quantity - 1
where id = v_ration.id;
v_rations_remaining := v_ration.quantity - 1;
end if;

update characters set hp = max_hp where id = p_character_id;
update character_features
set uses_current = uses_max
where character_id = p_character_id and uses_max is not null;
update character_spells
set lost = false,
succeeded_since_rest = false,
last_check_natural = null,
last_check_total = null,
last_check_succeeded = null,
last_check_at = null
where character_id = p_character_id;

insert into campaign_events (
campaign_id, actor_user_id, event_type, entity_type, entity_id, payload
) values (
v_character.campaign_id,
auth.uid(),
'character.full_rest_completed',
'character',
p_character_id,
jsonb_build_object(
'hp_before', v_character.hp,
'hp_after', v_character.max_hp,
'ration_item_id', v_ration.id,
'rations_remaining', v_rations_remaining
)
);

insert into scene_log (
campaign_id, type, sender_user_id, sender_name, text
) values (
v_character.campaign_id,
'narration',
auth.uid(),
v_character.name,
v_character.name || ' completed a full rest — HP restored to ' || v_character.max_hp || '/' || v_character.max_hp
);

return jsonb_build_object(
'character_id', p_character_id,
'hp', v_character.max_hp,
'rations_remaining', v_rations_remaining
);
end;
$$;

revoke all on function complete_character_rest(uuid) from public;
grant execute on function complete_character_rest(uuid) to authenticated;

-- Authoritative attack resolution: rolls to hit, compares against the
-- target's AC, and on a hit rolls damage and applies it to the target's
-- HP -- one audited server command, same shape as roll_campaign_dice.
--
-- Simplification, called out deliberately: a natural 20 always hits and a
-- natural 1 always misses (standard OSR house rule), but there is no
-- crit-damage multiplier -- Shadowdark's core rules don't define one, and
-- this isn't the place to invent a house rule that hasn't been decided.

create or replace function resolve_attack_roll(
  p_campaign_id uuid,
  p_attacker_name text,
  p_attack_notation text,
  p_damage_notation text,
  p_target_type text,
  p_target_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_attack jsonb;
  v_damage jsonb;
  v_target_ac int;
  v_target_hp int;
  v_target_max_hp int;
  v_target_name text;
  v_hit boolean;
  v_crit boolean;
  v_fumble boolean;
  v_damage_total int := 0;
  v_next_hp int;
  v_text text;
  v_scene scene_log%rowtype;
  v_attack_roll dice_rolls%rowtype;
begin
  if not is_campaign_member(p_campaign_id) then
    raise exception 'Campaign not found, or you are not a member.';
  end if;
  if p_target_type not in ('character', 'monster') then
    raise exception 'Unsupported target type.';
  end if;
  if length(coalesce(btrim(p_attacker_name), '')) = 0 or length(p_attacker_name) > 80 then
    raise exception 'Attacker name is required.';
  end if;

  if p_target_type = 'character' then
    select ac, hp, max_hp, name into v_target_ac, v_target_hp, v_target_max_hp, v_target_name
    from characters where id = p_target_id and campaign_id = p_campaign_id;
  else
    select ac, hp, max_hp, name into v_target_ac, v_target_hp, v_target_max_hp, v_target_name
    from encounter_monsters where id = p_target_id and campaign_id = p_campaign_id;
  end if;
  if v_target_name is null then
    raise exception 'Target not found in this campaign.';
  end if;

  v_attack := roll_dice_expression(p_attack_notation);
  v_crit := coalesce((v_attack->>'raw_d20')::int = 20, false);
  v_fumble := coalesce((v_attack->>'raw_d20')::int = 1, false);
  v_hit := v_crit or (not v_fumble and (v_attack->>'total')::int >= v_target_ac);

  insert into dice_rolls (
    campaign_id, roller_user_id, roller_name, notation, mode, reason,
    breakdown, total, raw_d20, is_crit, is_fumble
  ) values (
    p_campaign_id, auth.uid(), btrim(p_attacker_name),
    lower(regexp_replace(p_attack_notation, '\s+', '', 'g')), 'flat',
    'attack vs ' || v_target_name,
    v_attack->>'breakdown', (v_attack->>'total')::int,
    (v_attack->>'raw_d20')::int, v_crit, v_fumble
  ) returning * into v_attack_roll;

  v_next_hp := v_target_hp;
  if v_hit then
    v_damage := roll_dice_expression(p_damage_notation);
    v_damage_total := greatest(0, (v_damage->>'total')::int);
    v_next_hp := greatest(0, v_target_hp - v_damage_total);

    insert into dice_rolls (
      campaign_id, roller_user_id, roller_name, notation, mode, reason,
      breakdown, total
    ) values (
      p_campaign_id, auth.uid(), btrim(p_attacker_name),
      lower(regexp_replace(p_damage_notation, '\s+', '', 'g')), 'flat',
      'damage vs ' || v_target_name,
      v_damage->>'breakdown', v_damage_total
    );

    if p_target_type = 'character' then
      update characters set hp = v_next_hp where id = p_target_id;
    else
      update encounter_monsters set hp = v_next_hp where id = p_target_id;
    end if;
  end if;

  v_text := btrim(p_attacker_name) || ' attacks ' || v_target_name || ': '
    || (v_attack->>'total') || ' vs AC ' || v_target_ac
    || case
         when v_crit then ' — CRITICAL HIT!'
         when v_fumble then ' — fumble, automatic miss.'
         when v_hit then ' — hit.'
         else ' — miss.'
       end
    || case when v_hit then ' ' || v_damage_total || ' damage (' || v_target_name || ' now '
         || v_next_hp || '/' || v_target_max_hp || ' hp).' else '' end;

  insert into scene_log (
    campaign_id, type, sender_user_id, sender_name, text, roll_source, dice_roll_id
  ) values (
    p_campaign_id, 'roll', auth.uid(), btrim(p_attacker_name), v_text, 'app', v_attack_roll.id
  ) returning * into v_scene;

  return jsonb_build_object(
    'hit', v_hit,
    'crit', v_crit,
    'fumble', v_fumble,
    'attack_total', (v_attack->>'total')::int,
    'target_ac', v_target_ac,
    'damage', v_damage_total,
    'target_hp', v_next_hp,
    'target_max_hp', v_target_max_hp,
    'scene_entry', to_jsonb(v_scene)
  );
end;
$$;

revoke all on function resolve_attack_roll(uuid, text, text, text, text, uuid) from public;
grant execute on function resolve_attack_roll(uuid, text, text, text, text, uuid) to authenticated;

-- Dying, stabilizing, and monster morale -- the last three Milestone 1
-- combat mechanics named in docs/ROADMAP.md, mechanics pulled verbatim
-- from the table's own reference (gm-brain/_TOOLS/GM_QUICK_REFERENCE.md,
-- "Death" + "Morale" sections):
--
--   Death: 0 HP = unconscious and dying. Death timer = 1d4 + CON mod
--   (min 1) rounds; roll a d20 each subsequent turn, natural 20 = rise
--   with 1 HP. Stabilize: DC 15 INT check at close range (target stays
--   unconscious but stops dying). Perishing = character retired.
--
--   Morale: enemies reduced to half their number (or half HP for a solo
--   enemy) flee on a failed DC 15 WIS check.
--
-- Dying/stabilizing is PC-only -- monsters have no death timer, they just
-- die at 0 HP the way resolve_attack_roll already handles them. Morale is
-- monster-side only, doesn't touch HP or the death-timer state machine,
-- and is a GM-triggered roll-and-narrate check: this app doesn't try to
-- auto-detect "half the group" or force a check, since that's a judgment
-- call the GM makes about the specific encounter.

-- Small standard-table helper, mirrors src/game/rules/character.js
-- abilityModifier() exactly so server-side rolls (CON for death timers)
-- match client-side character sheet math.
create or replace function ability_modifier(p_score int)
returns int
language sql
immutable
as $$
  select case
    when p_score >= 18 then 4
    when p_score >= 16 then 3
    when p_score >= 14 then 2
    when p_score >= 12 then 1
    when p_score >= 10 then 0
    when p_score >= 8 then -1
    when p_score >= 6 then -2
    when p_score >= 4 then -3
    else -4
  end;
$$;

alter table characters
  add column if not exists status text not null default 'alive'
    check (status in ('alive', 'dying', 'stable', 'dead')),
  add column if not exists death_timer int;

-- Fires on every write to characters.hp regardless of how it got there
-- (resolve_attack_roll, a GM's manual HP nudge, a future heal command),
-- so "hit 0, start dying" can never be missed by only hooking one path.
create or replace function handle_character_hp_zero()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_con_mod int;
  v_timer_roll jsonb;
  v_timer int;
begin
  if new.hp = 0 and old.hp > 0 and new.status = 'alive' then
    v_con_mod := ability_modifier(coalesce((new.stats->>'con')::int, 10));
    v_timer_roll := roll_dice_expression('1d4');
    v_timer := greatest(1, (v_timer_roll->>'total')::int + v_con_mod);
    new.status := 'dying';
    new.death_timer := v_timer;

    insert into scene_log (campaign_id, type, sender_name, text)
    values (
      new.campaign_id, 'narration', 'System',
      new.name || ' drops to 0 HP and is dying. Death timer: ' || v_timer || ' round' || case when v_timer = 1 then '' else 's' end || '.'
    );
  elsif new.hp > 0 and old.status in ('dying', 'stable') then
    -- HP restored by any means while dying/stable clears the timer and
    -- wakes the character back up. The house rule only specifies the
    -- natural-20 recovery path; treating any HP-above-0 write the same
    -- way is the obvious extension rather than a new invented rule.
    new.status := 'alive';
    new.death_timer := null;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_character_hp_zero on characters;
create trigger trg_character_hp_zero
  before update of hp on characters
  for each row
  execute function handle_character_hp_zero();

-- Stabilize: DC 15 INT check against a dying character at Close range.
-- Success stops the death timer (target stays unconscious, stops dying);
-- failure just costs the attempt. Deliberate simplification: this checks
-- the *target's* zone is Close, not which specific character is making
-- the attempt -- the house rule only constrains the target's position.
create or replace function resolve_stabilize_check(
  p_campaign_id uuid,
  p_healer_name text,
  p_target_character_id uuid,
  p_int_notation text default '1d20'
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_target characters%rowtype;
  v_roll jsonb;
  v_success boolean;
  v_text text;
  v_scene scene_log%rowtype;
begin
  if not is_campaign_member(p_campaign_id) then
    raise exception 'Campaign not found, or you are not a member.';
  end if;
  if length(coalesce(btrim(p_healer_name), '')) = 0 or length(p_healer_name) > 80 then
    raise exception 'Healer name is required.';
  end if;

  select * into v_target from characters where id = p_target_character_id and campaign_id = p_campaign_id;
  if v_target.id is null then
    raise exception 'Target character not found in this campaign.';
  end if;
  if v_target.status <> 'dying' then
    raise exception '% is not dying.', v_target.name;
  end if;
  if coalesce(v_target.zone, 'near') <> 'close' then
    raise exception '% must be at Close range to stabilize.', v_target.name;
  end if;

  v_roll := roll_dice_expression(p_int_notation);
  v_success := (v_roll->>'total')::int >= 15;

  insert into dice_rolls (
    campaign_id, roller_user_id, roller_name, notation, mode, reason,
    breakdown, total, raw_d20, is_crit, is_fumble
  ) values (
    p_campaign_id, auth.uid(), btrim(p_healer_name),
    lower(regexp_replace(p_int_notation, '\s+', '', 'g')), 'flat',
    'stabilize ' || v_target.name,
    v_roll->>'breakdown', (v_roll->>'total')::int,
    (v_roll->>'raw_d20')::int, coalesce((v_roll->>'raw_d20')::int = 20, false), coalesce((v_roll->>'raw_d20')::int = 1, false)
  );

  if v_success then
    update characters set status = 'stable', death_timer = null where id = p_target_character_id;
  end if;

  v_text := btrim(p_healer_name) || ' attempts to stabilize ' || v_target.name || ': '
    || (v_roll->>'total') || ' vs DC 15 — '
    || case when v_success then 'success. ' || v_target.name || ' is stable.' else 'failure.' end;

  insert into scene_log (campaign_id, type, sender_user_id, sender_name, text, roll_source)
  values (p_campaign_id, 'roll', auth.uid(), btrim(p_healer_name), v_text, 'app')
  returning * into v_scene;

  return jsonb_build_object(
    'success', v_success,
    'total', (v_roll->>'total')::int,
    'target_status', (select status from characters where id = p_target_character_id),
    'scene_entry', to_jsonb(v_scene)
  );
end;
$$;

revoke all on function resolve_stabilize_check(uuid, text, uuid, text) from public;
grant execute on function resolve_stabilize_check(uuid, text, uuid, text) to authenticated;

-- Death check: rolled on a dying character's subsequent turn. Natural 20
-- rises with 1 HP; otherwise the death timer ticks down, and hitting 0
-- means the character perishes (status = 'dead', a retired character per
-- the house rule -- this app doesn't delete or otherwise special-case
-- that row, it just stops being playable).
create or replace function resolve_dying_turn(
  p_campaign_id uuid,
  p_character_id uuid
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_target characters%rowtype;
  v_roll jsonb;
  v_nat int;
  v_text text;
  v_scene scene_log%rowtype;
  v_next_timer int;
begin
  if not is_campaign_member(p_campaign_id) then
    raise exception 'Campaign not found, or you are not a member.';
  end if;

  select * into v_target from characters where id = p_character_id and campaign_id = p_campaign_id;
  if v_target.id is null then
    raise exception 'Character not found in this campaign.';
  end if;
  if v_target.status <> 'dying' then
    raise exception '% is not dying.', v_target.name;
  end if;

  v_roll := roll_dice_expression('1d20');
  v_nat := (v_roll->>'raw_d20')::int;

  insert into dice_rolls (
    campaign_id, roller_user_id, roller_name, notation, mode, reason,
    breakdown, total, raw_d20, is_crit, is_fumble
  ) values (
    p_campaign_id, auth.uid(), v_target.name, '1d20', 'flat', v_target.name || ' — death check',
    v_roll->>'breakdown', (v_roll->>'total')::int, v_nat, v_nat = 20, v_nat = 1
  );

  if v_nat = 20 then
    update characters set status = 'alive', hp = 1, death_timer = null where id = p_character_id;
    v_text := v_target.name || ' rolls a natural 20 on their death check and claws back to consciousness with 1 HP!';
  else
    v_next_timer := greatest(0, coalesce(v_target.death_timer, 1) - 1);
    if v_next_timer <= 0 then
      update characters set status = 'dead', death_timer = 0 where id = p_character_id;
      v_text := v_target.name || '''s death timer runs out. ' || v_target.name || ' has perished.';
    else
      update characters set death_timer = v_next_timer where id = p_character_id;
      v_text := v_target.name || ' is still dying (rolled ' || (v_roll->>'total') || '). Death timer: '
        || v_next_timer || ' round' || case when v_next_timer = 1 then '' else 's' end || ' remaining.';
    end if;
  end if;

  insert into scene_log (campaign_id, type, sender_user_id, sender_name, text, roll_source)
  values (p_campaign_id, 'roll', auth.uid(), v_target.name, v_text, 'app')
  returning * into v_scene;

  return jsonb_build_object(
    'status', (select status from characters where id = p_character_id),
    'death_timer', (select death_timer from characters where id = p_character_id),
    'nat20', v_nat = 20,
    'scene_entry', to_jsonb(v_scene)
  );
end;
$$;

revoke all on function resolve_dying_turn(uuid, uuid) from public;
grant execute on function resolve_dying_turn(uuid, uuid) to authenticated;

-- Morale: GM-triggered DC 15 WIS check for a monster group. Pass holds,
-- fail flees. GM supplies the modifier via notation (e.g. '1d20+1') same
-- as every other roll in this app -- no automatic "half the group" HP
-- detection, that threshold call stays with the GM.
create or replace function resolve_morale_check(
  p_campaign_id uuid,
  p_group_label text,
  p_wis_notation text default '1d20'
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_roll jsonb;
  v_success boolean;
  v_text text;
  v_scene scene_log%rowtype;
begin
  if not is_campaign_gm(p_campaign_id) then
    raise exception 'Only the GM can call a morale check.';
  end if;
  if length(coalesce(btrim(p_group_label), '')) = 0 or length(p_group_label) > 80 then
    raise exception 'Group label is required.';
  end if;

  v_roll := roll_dice_expression(p_wis_notation);
  v_success := (v_roll->>'total')::int >= 15;

  insert into dice_rolls (
    campaign_id, roller_user_id, roller_name, notation, mode, reason,
    breakdown, total, raw_d20, is_crit, is_fumble
  ) values (
    p_campaign_id, auth.uid(), btrim(p_group_label),
    lower(regexp_replace(p_wis_notation, '\s+', '', 'g')), 'flat', 'morale check',
    v_roll->>'breakdown', (v_roll->>'total')::int, (v_roll->>'raw_d20')::int,
    coalesce((v_roll->>'raw_d20')::int = 20, false), coalesce((v_roll->>'raw_d20')::int = 1, false)
  );

  v_text := btrim(p_group_label) || ' morale check: ' || (v_roll->>'total') || ' vs DC 15 — '
    || case when v_success then 'holds.' else 'breaks and flees!' end;

  insert into scene_log (campaign_id, type, sender_user_id, sender_name, text, roll_source)
  values (p_campaign_id, 'roll', auth.uid(), btrim(p_group_label), v_text, 'app')
  returning * into v_scene;

  return jsonb_build_object(
    'success', v_success,
    'total', (v_roll->>'total')::int,
    'scene_entry', to_jsonb(v_scene)
  );
end;
$$;

revoke all on function resolve_morale_check(uuid, text, text) from public;
grant execute on function resolve_morale_check(uuid, text, text) to authenticated;

